from contextlib import contextmanager
import os
import types
import asserts


def assert_file_content_equals(file_path, expected_contents):
    """Asserts that file at file_path exists and its contents are equal to expected_contents"""
    assert os.path.isfile(file_path), '%s is not a file' % file_path
    with open(file_path, 'r') as open_file:
        read = open_file.read()
        assert read == expected_contents


@contextmanager
def assert_raises_with_message(exception_with_message):
    """Asserts that the code wrapped by this context manager raises expected exception, including the message"""
    expected_message = str(exception_with_message)
    expected_type = type(exception_with_message)

    def _assert_has_message(e):
        asserts.assert_equal(expected_message, str(e))

    context = asserts.assert_raises(expected_type)
    context.add_test(_assert_has_message)
    with context:
        yield
